54	/** Least-loaded enabled+online node with account headroom. */
55	async function scheduleHostingNode(): Promise<{ id: string } | null> {
56	  const nodes = await db.hostingNode.findMany({ where: { enabled: true, status: "ONLINE" } });
57	  if (!nodes.length) return null;
58	  const loads = await Promise.all(
59	    nodes.map(async (n) => ({
60	      node: n,
61	      used: await db.hostingAccount.count({ where: { hostingNodeId: n.id, status: { in: [...LIVE_STATES] } } }),
62	    })),
63	  );
64	  const withRoom = loads.filter((l) => l.used < l.node.maxAccounts).sort((a, b) => a.used - b.used);
65	  return withRoom.length ? { id: withRoom[0].node.id } : null;
66	}
