68	/** A free jailed username on the node, derived from the email + random salt. */
69	async function pickUsername(nodeId: string, emailSeed: string): Promise<string> {
70	  for (let i = 0; i < 8; i++) {
71	    const name = deriveUsername(emailSeed, randomBytes(4).toString("hex"));
72	    if (!isValidUnixUsername(name)) continue;
73	    const taken = await db.hostingAccount.findUnique({ where: { hostingNodeId_username: { hostingNodeId: nodeId, username: name } } });
74	    if (!taken) return name;
75	  }
76	  throw new Error("Could not allocate a username — try again.");
77	}
