79	/**
80	 * Order a shared-hosting account for a domain on a plan. Same purchase discipline
81	 * as every other paid path: no spending while impersonating, verified email,
82	 * wallet charge in the same tx that creates the record. The account starts
83	 * PENDING; the worker provisioner brings it up (inert until shared hosting is
84	 * enabled — see worker/hosting.ts).
85	 */
86	export async function orderHostingAccount(
87	  planId: string,
88	  domain: string,
89	  termMonthsRaw?: number,
90	): Promise<HostingResult> {
91	  const user = await requireUser();
92	  await assertNotImpersonating();
93	  const unverified = await emailVerificationError(user);
94	  if (unverified) return { error: unverified };
95	
96	  // OPTIONAL domain. An empty domain means "start me on a free temporary
97	  // `<username>.nxeon.cloud` subdomain, I'll connect a real domain later" — the
98	  // customer is never forced to own a domain to sign up. A REAL domain keeps every
99	  // cross-tenant guard it always had; the temp subdomain is derived from the
100	  // account's own per-node-unique username (below) so it can't collide with
101	  // anything a customer typed, and its uniqueness is still enforced by the SAME
102	  // atomic UNIQUE(hostname) claim inside the charge tx.
103	  const wantTemp = !String(domain ?? "").trim();
104	  let name = "";
105	  if (!wantTemp) {
106	    name = normalizeHostingDomain(domain);
107	    if (!name) return { error: "Enter a domain." };
108	    if (!isValidHostingDomain(name)) return { error: "Enter a valid domain (e.g. example.com)." };
109	  }
110	
111	  const plan = await db.hostingPlan.findUnique({ where: { id: planId } });
112	  if (!plan || !plan.active) return { error: "That hosting plan isn’t available." };
113	
114	  if (!wantTemp) {
115	    // One account per domain across ALL customers — same cross-tenant guard as
116	    // email subscriptions (a shared vhost keys on server_name).
117	    const dupe = await db.hostingAccount.findFirst({ where: { primaryDomain: name, status: { in: [...LIVE_STATES] } } });
118	    if (dupe) {
119	      return {
120	        error:
121	          dupe.userId === user.id
122	            ? "You already have a hosting account for this domain."
123	            : "That domain is already hosted on Nxeon. If it’s yours, contact support to move it across.",
124	      };
125	    }
126	    // Also reject if this hostname is already someone's subdomain or addon domain
127	    // (audit HIGH-2: the primary-order guard used to ignore those two tables).
128	    if (await isHostnameClaimed(name)) {
129	      return { error: "That domain is already hosted on Nxeon. If it’s yours, contact support to move it across." };
130	    }
131	  }
132	
133	  const node = await scheduleHostingNode();
134	  if (!node) return { error: "No shared-hosting capacity is available right now — please try again shortly." };
135	
136	  // Managed first-month-free. `promoCharge` is $0 (a single-month hosting term is
137	  // free); `fullCharge` is the plan price. The credit is granted ONLY if the atomic
138	  // claim inside the charge tx succeeds — otherwise (already redeemed by this
139	  // account/IP, or the promo is off) the account is created at FULL price. We
140	  // pre-check eligibility only to pick the balance gate: a first-time customer with
141	  // a $0 balance can still sign up free, a repeat one is gated against full price.
142	  // First-month-free is scoped to Shared Web Hosting (this flow) — the one
143	  // product the promo applies to. See firstMonthFreeAppliesTo.
144	  const promoEnabled = firstMonthFreeAppliesTo("HOSTING") && (await firstMonthFreeEnabled());
145	  const campaign = promoCampaignFromCookie(await cookies());
146	  const ipHash = hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon") || null;
147	  // Billing term (Monthly / Annual). The annual rate is the admin setting, resolved
148	  // ONCE here, frozen onto the account, charged up front and read back at renewal —
149	  // so displayed === charged === renewed. A malformed term falls back to monthly.
150	  const term = normalizeProductTerm(termMonthsRaw);
151	  const annualPct = await annualDiscountPct();
152	  const fullCharge = termPriceCents(plan.priceCents, term, annualPct);
153	  // First-month-free must credit EXACTLY ONE MONTH — never zero a whole annual term.
154	  // `firstMonthCreditCents(fullCharge, term)` returns the full charge for a 1-month
155	  // term (genuinely free first month, $0) and one month's share for the annual term,
156	  // so annual + promo = "one month credited, the other 11 months charged".
157	  const promoCharge = Math.max(0, fullCharge - firstMonthCreditCents(fullCharge, term));
158	  const eligible = promoEnabled && (await firstMonthFreeEligible(user.id, ipHash));
159	  const anticipated = eligible ? promoCharge : fullCharge;
160	  if (user.balanceCents < anticipated) return { error: "Insufficient balance. Top up your wallet first." };
161	
162	  const limits = planLimits(plan);
163	  const username = await pickUsername(node.id, user.email.split("@")[0] ?? "acct");
164	  // Free temporary subdomain: derived from the just-allocated (per-node-unique)
165	  // username, validated the same way a real domain is and de-duplicated by the same
166	  // atomic hostname claim inside the tx. The advisory pre-check here is friendly UX
167	  // only — a collision across nodes is caught authoritatively by UNIQUE(hostname).
168	  if (wantTemp) {
169	    name = tempSubdomainFor(username);
170	    if (!isValidHostingDomain(name)) return { error: "Couldn’t allocate a temporary subdomain — please try again." };
171	    if (await isHostnameClaimed(name)) return { error: "Couldn’t allocate a temporary subdomain — please try again." };
172	  }
173	
174	  let accountId = "";
175	  try {
176	    await db.$transaction(async (tx) => {
177	      // Atomic claim inside the charge tx (mirrors lib/order.ts claimOrderCoupon).
178	      let debitCents = fullCharge;
179	      let promoClaimId: string | null = null;
180	      if (promoEnabled) {
181	        const claim = await claimFirstMonthFree(tx, {
182	          userId: user.id,
183	          ipHash,
184	          serviceType: "HOSTING",
185	          campaign,
186	          chargedCents: promoCharge,
187	        });
188	        if (claim.claimed) {
189	          debitCents = promoCharge;
190	          promoClaimId = claim.id;
191	        }
192	      }
193	      const note = debitCents < fullCharge ? " — First month free" : "";
194	      // Term shown on the ledger line: an annual account reads "Annual ($X.XX/mo)"
195	      // so the customer sees the yearly commitment AND its real per-month rate.
196	      const effMonthly = term > 1 ? Math.round(fullCharge / term) : 0;
197	      const termLabel = term > 1 ? `${vpsTerm(term).label} ($${(effMonthly / 100).toFixed(2)}/mo)` : vpsTerm(term).label;
198	      await debitWallet(tx, user.id, debitCents);
199	      await tx.walletTransaction.create({
200	        data: { userId: user.id, amountCents: -debitCents, description: `Web Hosting: ${plan.name} for ${name} — ${termLabel}${note}` },
201	      });
202	      const acct = await tx.hostingAccount.create({
203	        // Cast: the symlinked prod Prisma client's types predate `termMonths` /
204	        // `annualDiscountPct` on HostingAccount until it is regenerated at deploy
205	        // (identical at runtime then — see lib/order.ts's Server create).
206	        data: {
207	          userId: user.id,
208	          hostingNodeId: node.id,
209	          planId: plan.id,
210	          username,
211	          primaryDomain: name,
212	          status: "PENDING",
213	          diskQuotaMB: limits.diskGB * 1024,
214	          maxSites: limits.maxSites,
215	          maxDatabases: limits.maxDatabases,
216	          // The term this account was SOLD on, and the annual rate frozen at sale, so
217	          // the renewal sweep bills the SAME price it was ordered at (worker/product-renewals.ts).
218	          termMonths: term,
219	          annualDiscountPct: annualPct,
220	          expiresAt: addMonths(new Date(), term),
221	        } as Prisma.HostingAccountUncheckedCreateInput,
222	      });
223	      accountId = acct.id;
224	      // Atomic hostname claim in the SAME tx as the account row. A colliding
225	      // primaryDomain (another order, or someone's subdomain/addon of the same
226	      // name racing us past the advisory isHostnameClaimed check) fails here on
227	      // UNIQUE(hostname) → the whole tx (incl. the wallet debit) rolls back.
228	      await tx.hostingHostnameClaim.create({ data: { hostname: normalizeClaimHostname(name), accountId: acct.id, kind: "PRIMARY" } });
229	      if (promoClaimId) await setPromoOrderRef(tx, promoClaimId, acct.id, debitCents);
230	    });
231	  } catch (e) {
232	    if (isUniqueViolation(e)) {
233	      return { error: "That domain is already hosted on Nxeon. If it’s yours, contact support to move it across." };
234	    }
235	    return { error: "Couldn’t place the order. Your wallet was not charged — try again." };
236	  }
237	
238	  await db.auditLog.create({ data: { userId: user.id, action: "hosting.order", detail: `${plan.name} · ${name}` } }).catch(() => {});
239	  revalidatePath("/dashboard/hosting");
240	  return { ok: true, accountId };
241	}
