243	// ---------- Checkout wizard (payment-method-captured order) ------------------
244	//
245	// THE MONEY FIX. `orderHostingAccount` above debits the WALLET only. First-month-
246	// free (hosting-only) makes a monthly plan $0 for month 1, so the wallet path used
247	// to provision with NOTHING on file — and month-2's renewal had nothing to charge.
248	// `placeHostingOrder` is the wizard's single entry point and closes that gap: it
249	// REFUSES to provision unless the account has a way to bill the renewal (a saved
250	// card OR a wallet balance that already covers one renewal), it is idempotent
251	// against double-submit, and it then delegates the ACTUAL charge to the audited
252	// `orderHostingAccount` above — one debit path, never a second one.
253	//
254	// displayed === charged === renewed: this action computes NO price of its own for
255	// the debit. The wallet debit + the first-month-free reserve→confirm→release
256	// atomicity all live inside `orderHostingAccount`; `renewalCents` here is only the
257	// gate threshold and is the SAME `termPriceCents(plan.priceCents, term, annualPct)`
258	// the renewal sweep charges (worker/product-renewals.ts hostingRenewalPrice).
259	
260	export type HostingOrderInput = {
261	  planId: string;
262	  /** Empty/omitted => free temporary `<username>.nxeon.cloud` subdomain. */
263	  domain?: string;
264	  termMonths?: number;
265	  /** Optional catalog app to auto-install after the account provisions. */
266	  appSlug?: string;
267	  /** Client-generated token that makes a resubmit a no-op (double-submit guard). */
268	  idempotencyKey: string;
269	};
270	
271	export type HostingOrderResult =
272	  | { ok: true; accountId: string }
273	  | { error: string }
274	  /** No renewal-capable payment method yet — the wizard must capture a card first. */
275	  | { needCard: true; renewalCents: number };
276	
277	/**
278	 * The full-price single renewal of a plan/term — the gate threshold, identical to
279	 * what the renewal sweep bills so "wallet covers a renewal" means exactly that.
280	 */
281	async function hostingRenewalCents(plan: { priceCents: number }, term: number): Promise<number> {
282	  const annualPct = await annualDiscountPct();
283	  return termPriceCents(plan.priceCents, term, annualPct);
284	}
