286	/** Place a hosting order from the checkout wizard. See the block comment above. */
287	export async function placeHostingOrder(input: HostingOrderInput): Promise<HostingOrderResult> {
288	  const user = await requireUser();
289	  await assertNotImpersonating();
290	  const unverified = await emailVerificationError(user);
291	  if (unverified) return { error: unverified };
292	
293	  const key = String(input.idempotencyKey ?? "").trim();
294	  if (!/^[A-Za-z0-9_-]{8,64}$/.test(key)) return { error: "Couldn’t place the order — please reload and try again." };
295	
296	  const term = normalizeProductTerm(input.termMonths);
297	  const plan = await db.hostingPlan.findUnique({ where: { id: input.planId } });
298	  if (!plan || !plan.active) return { error: "That hosting plan isn’t available." };
299	
300	  // RENEWAL-METHOD GATE — the core fix. Never provision a paid product with no way
301	  // to bill the renewal. A saved card (charged off-session by the renewal sweep) OR
302	  // a wallet already holding one renewal's worth qualifies; otherwise the wizard
303	  // sends the customer to Stripe to capture a card (which also handles the $0-today
304	  // case, where no card would otherwise be collected).
305	  const renewalCents = await hostingRenewalCents(plan, term);
306	  if (!hasChargeableCard(user) && user.balanceCents < renewalCents) {
307	    return { needCard: true, renewalCents };
308	  }
309	
310	  // IDEMPOTENCY — reuse the audited FulfilledSession one-winner primitive (its
311	  // UNIQUE(stripeSessionId) is what the card path leans on) rather than inventing a
312	  // token table. A rapid resubmit or a network retry with the same key can't create
313	  // a second account or take a second debit.
314	  const sessionKey = `hostorder:${key}`;
315	  try {
316	    await db.fulfilledSession.create({ data: { stripeSessionId: sessionKey, kind: "hostorder" } });
317	  } catch (e) {
318	    if (isUniqueViolation(e)) {
319	      const prior = await db.fulfilledSession.findUnique({ where: { stripeSessionId: sessionKey } });
320	      // A completed prior attempt: replay its result (no second charge).
321	      if (prior?.status === "DONE" && prior.detail) return { ok: true, accountId: prior.detail };
322	      // A failed prior attempt: clear it so an explicit retry can proceed.
323	      if (prior?.status === "FAILED") {
324	        await db.fulfilledSession.delete({ where: { stripeSessionId: sessionKey } }).catch(() => {});
325	      } else {
326	        // Still in flight (CLAIMED): a concurrent submit is placing it right now.
327	        return { error: "That order is already being placed — check your hosting accounts in a moment." };
328	      }
329	      // Retry after clearing a FAILED marker: re-claim, or bail if we lost the race.
330	      try {
331	        await db.fulfilledSession.create({ data: { stripeSessionId: sessionKey, kind: "hostorder" } });
332	      } catch {
333	        return { error: "That order is already being placed — check your hosting accounts in a moment." };
334	      }
335	    } else {
336	      throw e;
337	    }
338	  }
339	
340	  // Delegate the ACTUAL charge to the audited wallet path. An empty domain routes to
341	  // the free temporary subdomain. All money movement, the first-month-free atomic
342	  // claim and the hostname claim happen inside orderHostingAccount's transaction.
343	  const res = await orderHostingAccount(input.planId, input.domain ?? "", term);
344	  if (res.error || !res.accountId) {
345	    await db.fulfilledSession
346	      .update({ where: { stripeSessionId: sessionKey }, data: { status: "FAILED", detail: (res.error ?? "order failed").slice(0, 500) } })
347	      .catch(() => {});
348	    return { error: res.error ?? "Couldn’t place the order. Your wallet was not charged — try again." };
349	  }
350	  await db.fulfilledSession
351	    .update({ where: { stripeSessionId: sessionKey }, data: { status: "DONE", detail: res.accountId } })
352	    .catch(() => {});
353	
354	  // Optional one-click app install: queue it now so the worker installs it the
355	  // moment the account finishes provisioning. Best-effort — a bad slug never voids
356	  // the (already-charged) order; the customer can install from the panel later.
357	  const slug = String(input.appSlug ?? "").trim();
358	  if (slug) {
359	    try {
360	      await queueHostingAppInstall(res.accountId, slug, plan.maxDatabases, user.email);
361	    } catch {
362	      /* non-fatal: the account is created and charged; the app can be installed later */
363	    }
364	  }
365	
366	  revalidatePath("/dashboard/hosting");
367	  return { ok: true, accountId: res.accountId };
368	}
