370	/**
371	 * Queue an APP_INSTALL for a freshly-ordered (PENDING) account. Mirrors installApp
372	 * but without the ACTIVE gate — the task waits in the queue and the worker runs it
373	 * after provisioning. Generates DB credentials up front for apps that need one.
374	 */
375	async function queueHostingAppInstall(accountId: string, slug: string, maxDatabases: number, email: string): Promise<void> {
376	  const app = hostingAppCatalog().find((x) => x.slug === slug);
377	  if (!app) return;
378	  let payload: Record<string, unknown> = { slug };
379	  if (app.needsDb) {
380	    if (maxDatabases < 1) return; // the plan has no DB budget — skip rather than fail
381	    const acct = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { username: true } });
382	    if (!acct) return;
383	    const dbName = `${acct.username}_${slug}`.slice(0, 64);
384	    const dbUser = dbName.slice(0, 32);
385	    const dbPass = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 20);
386	    payload = { slug, dbName, dbUser, dbPassEnc: encryptSecret(dbPass) };
387	  }
388	  void email;
389	  await db.hostingTask.create({ data: { accountId, kind: "APP_INSTALL", payload: JSON.stringify(payload) } });
390	}
