392	/**
393	 * Begin capturing a renewal payment method for the hosting wizard. A Stripe hosted
394	 * Checkout in `mode: "setup"` records a card + off-session mandate WITHOUT charging
395	 * anything — the answer to "a $0 first month must still capture a card for renewal".
396	 * Returns to the hosting page; the wizard finalises via finalizeCardSetup (shared).
397	 */
398	export async function startHostingCardSetup(): Promise<{ url?: string; error?: string }> {
399	  await assertNotImpersonating();
400	  const user = await requireUser();
401	  if (!stripeConfigured()) return { error: "Card payments aren’t configured on this installation yet." };
402	  try {
403	    const url = await createCardSetupSession(user, "/dashboard/hosting");
404	    if (!url) return { error: "Stripe didn’t return a setup link. Please try again." };
405	    await db.auditLog.create({ data: { userId: user.id, action: CARD_SETUP_STARTED } });
406	    return { url };
407	  } catch (e) {
408	    console.error("[hosting] card setup session failed", e);
409	    return { error: "We couldn’t start card setup just now. Please try again in a moment." };
410	  }
411	}
