445	function toView(a: {
446	  id: string; primaryDomain: string; status: string; username: string; diskQuotaMB: number; maxSites: number;
447	  maxDatabases: number; sslActive: boolean; phpVersion: string; error: string | null; expiresAt: Date | null; createdAt: Date;
448	  dbToolPath?: string | null;
449	  diskUsedMB?: number | null; inodesUsed?: number | null; usageAt?: Date | null;
450	  serveHttpOk?: boolean | null; serveHttpsOk?: boolean | null; healthNote?: string | null; healthCheckedAt?: Date | null;
451	  plan: { name: string; phpVersions: string }; node: { publicIp: string; hostnameFqdn: string | null };
452	}): HostingAccountView {
453	  const pt = pointToRecords(a.node);
454	  return {
455	    id: a.id, primaryDomain: a.primaryDomain, planName: a.plan.name, status: a.status, username: a.username,
456	    pointToA: pt.aRecord, pointToCname: pt.cnameTarget, diskQuotaMB: a.diskQuotaMB, maxSites: a.maxSites,
457	    diskUsedMB: a.diskUsedMB ?? null, inodesUsed: a.inodesUsed ?? null, usageAt: a.usageAt?.toISOString() ?? null,
458	    maxDatabases: a.maxDatabases, sslActive: a.sslActive, phpVersion: a.phpVersion,
459	    serveHttpOk: a.serveHttpOk ?? null, serveHttpsOk: a.serveHttpsOk ?? null,
460	    healthNote: a.healthNote ?? null, healthCheckedAt: a.healthCheckedAt?.toISOString() ?? null,
