537	/** Create a scoped database for an account (within the plan's maxDatabases). */
538	export async function createHostingDatabase(accountId: string, label: string): Promise<{ error?: string; ok?: boolean; password?: string }> {
539	  const user = await requireUser();
540	  await assertNotImpersonating();
541	  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { id: true, userId: true, status: true, username: true, maxDatabases: true } });
542	  if (!a) return { error: "Account not found." };
543	  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
544	  if (a.status !== "ACTIVE") return { error: "The account is still being set up." };
545	  // A short, safe suffix keyed off the account username: <user>_<slug>.
546	  const slug = String(label ?? "").toLowerCase().replace(/[^a-z0-9]/g, "").slice(0, 12) || "db";
547	  const name = `${a.username}_${slug}`.slice(0, 64);
548	  const dbUser = name.slice(0, 32);
549	  if (!/^[a-z0-9_]{1,64}$/.test(name)) return { error: "Invalid database name." };
550	  const password = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 20);
551	  // Count + create in ONE serializable transaction, so concurrent creates can't
552	  // both read a stale count and blow past the plan cap (audit 2026-08-01 TOCTOU).
553	  try {
554	    await db.$transaction(async (tx) => {
555	      const n = await tx.hostingDatabase.count({ where: { accountId: a.id, status: { in: ["PENDING", "ACTIVE"] } } });
556	      if (n >= a.maxDatabases) throw new Error("CAP");
557	      await tx.hostingDatabase.create({ data: { accountId: a.id, name, dbUser, passwordEnc: encryptSecret(password), status: "PENDING" } });
558	    }, { isolationLevel: "Serializable" });
559	  } catch (e) {
560	    if (e instanceof Error && e.message === "CAP") return { error: `Your plan allows ${a.maxDatabases} database${a.maxDatabases === 1 ? "" : "s"}.` };
561	    // Serialization conflict (P2034) or the unique(accountId,name) collision.
562	    return { error: "A database with that name already exists, or the request raced — try again." };
563	  }
564	  revalidatePath("/dashboard/hosting");
565	  // Shown ONCE — the encrypted copy is cleared by the provisioner after it applies it.
566	  return { ok: true, password };
567	}
