728	/**
729	 * Move a hosting account UP to a larger plan. Same purchase discipline as
730	 * orderHostingAccount: no spending while impersonating, wallet charge in the same
731	 * tx that mutates the account.
732	 *
733	 * Billing choice (kept simple + honest): we charge the FULL per-term price
734	 * DIFFERENCE (new − current) now, and leave the renewal date unchanged; future
735	 * terms bill at the new plan price. No mid-term proration or refunds — that keeps
736	 * the flow one debit and never owes the customer money back. The customer sees the
737	 * exact delta before confirming. Only UP is allowed (a downgrade would need a
738	 * refund path we don't have).
739	 */
740	export async function upgradeHostingPlan(accountId: string, newPlanId: string): Promise<HostingResult> {
741	  const user = await requireUser();
742	  await assertNotImpersonating();
743	  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, include: { plan: true } });
744	  if (!a) return { error: "Account not found." };
745	  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
746	  if (a.status !== "ACTIVE") return { error: "The account is still being set up." };
747	  const newPlan = await db.hostingPlan.findUnique({ where: { id: newPlanId } });
748	  if (!newPlan || !newPlan.active) return { error: "That plan isn’t available." };
749	  if (newPlan.id === a.planId) return { error: "You’re already on this plan." };
750	  const cur = a.plan;
751	  // Up-only guard (re-checked server-side; never trust the client's picker).
752	  if (newPlan.priceCents < cur.priceCents || newPlan.diskGB < cur.diskGB) {
753	    return { error: "You can only move to a larger plan." };
754	  }
755	  const limits = planLimits(newPlan);
756	  const chargeCents = Math.max(0, newPlan.priceCents - cur.priceCents);
757	  if (user.balanceCents < chargeCents) return { error: "Insufficient balance. Top up your wallet first." };
758	
759	  try {
760	    await db.$transaction(async (tx) => {
761	      if (chargeCents > 0) {
762	        await debitWallet(tx, user.id, chargeCents);
763	        await tx.walletTransaction.create({
764	          data: { userId: user.id, amountCents: -chargeCents, description: `Web Hosting upgrade: ${cur.name} → ${newPlan.name} for ${a.primaryDomain}` },
765	        });
766	      }
767	      // Snapshot the new plan's limits onto the account (same as orderHostingAccount
768	      // does at creation), so a later plan edit can't silently re-quota this account.
769	      // phpVersion is left as-is: an upgrade only widens the allowed set.
770	      await tx.hostingAccount.update({
771	        where: { id: a.id },
772	        data: { planId: newPlan.id, diskQuotaMB: limits.diskGB * 1024, maxSites: limits.maxSites, maxDatabases: limits.maxDatabases },
773	      });
774	      // Enact the node-level change (raise disk quota + rewrite FPM pool).
775	      await tx.hostingTask.create({ data: { accountId: a.id, kind: "APPLY_PLAN_LIMITS" } });
776	    });
777	  } catch (e) {
778	    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance. Top up your wallet first." };
779	    return { error: "Couldn’t upgrade the plan. Your wallet was not charged — try again." };
780	  }
781	
782	  await db.auditLog.create({ data: { userId: user.id, action: "hosting.upgrade", detail: `${cur.name} → ${newPlan.name} · ${a.primaryDomain}` } }).catch(() => {});
783	  revalidatePath(`/dashboard/hosting/${accountId}`);
784	  return { ok: true };
785	}
