896	 * `server_name`, and a hostname can live in THREE places — a primary domain, a
897	 * subdomain, or an addon domain. Before this, each creator only checked its own
898	 * table, so an addon could shadow a victim's subdomain (or vice-versa) on a
899	 * co-located node = cross-tenant vhost takeover (security audit HIGH-1/HIGH-2).
900	 *
901	 * This is now a FAST, FRIENDLY PRE-CHECK only — good UX (an early, clear error)
902	 * but NOT trusted alone: a non-atomic read can't stop two concurrent requests
903	 * from both passing it and both committing the same server_name (the co-tenant
904	 * vhost-shadowing TOCTOU). The authoritative guard is the atomic UNIQUE(hostname)
905	 * insert into HostingHostnameClaim done INSIDE each creator's transaction — a
906	 * colliding claim fails there (P2002) and rolls the whole tx back.
907	 */
908	async function isHostnameClaimed(name: string): Promise<boolean> {
909	  // The authoritative registry (single UNIQUE(hostname) spanning all three kinds)
910	  // is the fast, definitive pre-check now. We also still scan the three resource
911	  // tables so any legacy row created before the claims table existed is honoured.
912	  const host = normalizeClaimHostname(name);
913	  const [claim, prim, sub, addon] = await Promise.all([
914	    db.hostingHostnameClaim.count({ where: { hostname: host } }),
915	    db.hostingAccount.count({ where: { primaryDomain: name, status: { in: [...LIVE_STATES] } } }),
916	    db.hostingSubdomain.count({ where: { fqdn: name, status: { in: [...SITE_STATES] } } }),
917	    db.hostingAddonDomain.count({ where: { domain: name, status: { in: [...SITE_STATES] } } }),
918	  ]);
