964	export async function createSubdomain(accountId: string, label: string): Promise<HostingResult> {
965	  const ctx = await ownedSiteAccount(accountId);
966	  if ("error" in ctx) return { error: ctx.error };
967	  const { a } = ctx;
968	  const clean = String(label ?? "").trim().toLowerCase();
969	  if (!isValidSubdomainLabel(clean)) return { error: "Enter a valid subdomain label — letters, digits and hyphens only." };
970	  const fqdn = `${clean}.${a.primaryDomain}`;
971	  if (!isValidHostingDomain(fqdn)) return { error: "That subdomain isn’t a valid hostname." };
972	  // Reject if another tenant already claimed this exact hostname as an addon domain
973	  // (or primary). fqdn @unique blocks subdomain↔subdomain; this closes the addon
974	  // path (audit HIGH-1, reverse direction).
975	  if (await isHostnameClaimed(fqdn)) {
976	    return { error: "That hostname is already in use on Nxeon." };
977	  }
978	  const { docroot } = subdomainPaths(a.username, clean);
979	  try {
980	    await db.$transaction(async (tx) => {
981	      const subs = await tx.hostingSubdomain.count({ where: { accountId: a.id, status: { in: [...SITE_STATES] } } });
982	      const addons = await tx.hostingAddonDomain.count({ where: { accountId: a.id, status: { in: [...SITE_STATES] } } });
983	      if (subs + addons >= a.maxSites) throw new Error("CAP");
984	      const sub = await tx.hostingSubdomain.create({ data: { accountId: a.id, label: clean, fqdn, docroot, status: "PENDING" } });
985	      // Atomic cross-tenant claim in the SAME tx: the UNIQUE(hostname) — not the
986	      // advisory isHostnameClaimed read above — is what actually stops a co-tenant
987	      // from committing this same server_name as their primary/subdomain/addon.
988	      await tx.hostingHostnameClaim.create({ data: { hostname: normalizeClaimHostname(fqdn), accountId: a.id, kind: "SUBDOMAIN" } });
989	      await tx.hostingTask.create({ data: { accountId: a.id, kind: "CREATE_SUBDOMAIN", payload: JSON.stringify({ subdomainId: sub.id }) } });
990	    }, { isolationLevel: "Serializable" });
991	  } catch (e) {
