16	export async function debitWallet(
17	  tx: Prisma.TransactionClient,
18	  userId: string,
19	  cents: number
20	): Promise<void> {
21	  if (cents <= 0) return;
22	  const res = await tx.user.updateMany({
23	    where: { id: userId, balanceCents: { gte: cents } },
24	    data: { balanceCents: { decrement: cents } },
25	  });
26	  if (res.count === 0) throw new InsufficientBalanceError();
